using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class BrokerWorkTests
{
 static readonly EntityId Issuer=new("person:nobunaga"),Job=new("job:broker-test");
 internal static WorldSession Start()=>HouseholdCourtTests.Start(HouseholdCourtTests.Retainer.Value);
 static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 static BrokerInput Input(WorldSession s,BrokerAction a)=>new(new("request:broker/"+s.Revision),a,Job);
 static WorldSession Accepted(){var s=Start();Good(s.ManageBroker(new(Job,BrokerAction.Accept,Issuer:Issuer,Kind:BrokerKind.Purchase),s.Revision));return s;}
 [Fact]public void PurchaseDeliverySettlementConservesActualMoneyAndMerchantWood(){var s=Accepted();var w=s.DiagnosticSnapshot();Assert.Equal(850,NewGameWork.Balance(w,Issuer));Assert.Equal(1000,NewGameWork.Balance(w,s.PlayerControl));long wood=w.Trade!.Markets.Single(m=>m.Site==HouseholdCourtTests.Site).Goods!.Single(g=>g.Kind=="wood").Quantity;Good(s.ManageBroker(Input(s,BrokerAction.Buy),s.Revision));w=s.DiagnosticSnapshot();long cost=w.BrokerWork!.Entries.Single(e=>e.Input.Action==BrokerAction.Buy).Cost;Assert.Equal(wood-5,w.Trade!.Markets.Single(m=>m.Site==HouseholdCourtTests.Site).Goods!.Single(g=>g.Kind=="wood").Quantity);Good(s.ManageBroker(Input(s,BrokerAction.Deliver),s.Revision));Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));var i=Input(s,BrokerAction.Settle);Good(s.ManageBroker(i,s.Revision));w=s.DiagnosticSnapshot();Assert.Equal(1050,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(1000-cost-50,NewGameWork.Balance(w,Issuer));Assert.Equal(5,BrokerWork.Deposited(w,Issuer));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageBroker(i,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageBroker(Input(s,BrokerAction.Settle),s.Revision).Code);ContractValidation.Validate(w);}
 [Fact]public void ReturnRestoresEscrowWithoutCreatingReward(){var s=Accepted();Good(s.ManageBroker(Input(s,BrokerAction.Return),s.Revision));Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Issuer));Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
 [Fact]public void LatePurchaseCannotSpendAndCanReturnAdvance(){var s=Accepted();NewGameWorldTests.At(s,31*86400);Assert.Equal(ResultCode.NotAvailable,s.ManageBroker(Input(s,BrokerAction.Buy),s.Revision).Code);Good(s.ManageBroker(Input(s,BrokerAction.Return),s.Revision));}
 [Fact]public void CannotSettleBeforeActualReceiptOrAcceptSecondUnsettledJob(){var s=Accepted();var raw=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageBroker(Input(s,BrokerAction.Settle),s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageBroker(new(new("job:second"),BrokerAction.Accept,Issuer:Issuer,Kind:BrokerKind.Purchase),s.Revision).Code);Assert.Equal(raw,ContractJson.Write(s.DiagnosticSnapshot()));}
 [Fact]public void RealGenerationSaveAfterPurchaseHasSameSettlementFuture(){var s=Accepted();Good(s.ManageBroker(Input(s,BrokerAction.Buy),s.Revision));s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"broker-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"cargo",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("cargo"),host.Current,host.Current.Revision));foreach(var x in new[]{s,host.Current}){Good(x.ManageBroker(Input(x,BrokerAction.Deliver),x.Revision));Good(x.ManageBroker(Input(x,BrokerAction.Settle),x.Revision));}Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
 [Fact]public void OptionalStateDoesNotChangeOldSaveBytes(){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Null(s.DiagnosticSnapshot().BrokerWork);Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));var legacy=ContractFixture.Create();legacy.BrokerWork=new(1,BrokerWork.Policy,[]);Assert.Throws<InvalidDataException>(()=>new WorldSession(legacy));}
 [Fact]public void DuplicateSettlementInForgedSaveIsRejected(){var s=Accepted();Good(s.ManageBroker(Input(s,BrokerAction.Return),s.Revision));var w=s.DiagnosticSnapshot();var e=w.BrokerWork!.Entries.Last();w.CommitSequence++;w.BrokerWork=w.BrokerWork with{Entries=[..w.BrokerWork.Entries,e with{Input=e.Input with{Id=new("request:forged-repeat")},Revision=w.CommitSequence}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void PrivateConsultationRequiresKnownRespect(){var s=Start();Assert.Empty(BrokerWork.Offers(s.DiagnosticSnapshot(),s.PlayerControl,Job,BrokerKind.Purchase,true));Assert.NotEmpty(BrokerWork.Offers(s.DiagnosticSnapshot(),s.PlayerControl,Job,BrokerKind.Purchase));}
 [Fact]public void NpcUsesTheSamePurchaseAndReceiptLedger(){var s=HouseholdCourtTests.Start();var w=s.DiagnosticSnapshot();var actor=HouseholdCourtTests.Retainer;w.CommitSequence++;BrokerWork.Execute(w,new(Job,BrokerAction.Accept,Issuer:Issuer,Kind:BrokerKind.Purchase),actor);typeof(NewGameWork).GetMethod("Sync",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic)!.Invoke(null,[w]);s=new(w);NewGameWorldTests.At(s,1);NewGameWorldTests.At(s,2);NewGameWorldTests.At(s,3);Assert.Equal("精算済み",BrokerWork.Jobs(s.DiagnosticSnapshot()).Single().Phase);Assert.Equal(1050,NewGameWork.Balance(s.DiagnosticSnapshot(),actor));}

 internal static WorldSession LetterStart(){var people=new[]{NewGameWorldTests.Officer("created:letter-worker",StartTemplate.Retainer,"castle:kofu","person:shingen"),NewGameWorldTests.Officer("created:letter-recipient",StartTemplate.Retainer,"site:suwa","person:shingen")};var setup=NewGameWorldTests.Setup(people);return new(NewGameWorld.Create(setup.World,setup.Registered,"created:letter-worker",42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy));}
 [Fact]public void SealedLetterRequiresActualRoundTripAndPhysicalReceipt(){var s=LetterStart();var offer=BrokerWork.Offers(s.DiagnosticSnapshot(),s.PlayerControl,Job,BrokerKind.Letter).Single(t=>t.Issuer.Value=="person:shingen");Good(s.ManageBroker(new(Job,BrokerAction.Accept,Issuer:offer.Issuer),s.Revision));Assert.Equal(ResultCode.NotAvailable,s.ManageBroker(Input(s,BrokerAction.Deliver),s.Revision).Code);TransportWorkTests.Travel(s,"suwa");Good(s.ManageBroker(Input(s,BrokerAction.Deliver),s.Revision));Assert.Equal(ResultCode.NotAvailable,s.ManageBroker(Input(s,BrokerAction.Settle),s.Revision).Code);TransportWorkTests.Travel(s,"kofu");Good(s.ManageBroker(Input(s,BrokerAction.Settle),s.Revision));Assert.Equal(1030,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Contains(WorkRelations.Facts(s.DiagnosticSnapshot(),offer.Issuer,s.PlayerControl),f=>f.Kind.Contains("受領証"));}
 [Fact]public void LateReceiptIsPreservedButDoesNotEarnThePromisedFee(){var s=Accepted();Good(s.ManageBroker(Input(s,BrokerAction.Buy),s.Revision));NewGameWorldTests.At(s,31*86400);Good(s.ManageBroker(Input(s,BrokerAction.Deliver),s.Revision));Good(s.ManageBroker(Input(s,BrokerAction.Settle),s.Revision));Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.False(BrokerWork.Jobs(s.DiagnosticSnapshot()).Single().Success);}
 [Fact]public void ACompletedSmallJobUnlocksLargerPrivateConsultation(){var s=Accepted();Good(s.ManageBroker(Input(s,BrokerAction.Buy),s.Revision));Good(s.ManageBroker(Input(s,BrokerAction.Deliver),s.Revision));Good(s.ManageBroker(Input(s,BrokerAction.Settle),s.Revision));Assert.Contains(BrokerWork.Offers(s.DiagnosticSnapshot(),s.PlayerControl,new("job:larger"),BrokerKind.Purchase,true),t=>t.Issuer==Issuer&&t.Fee==100&&t.Advance==300);}
 [Fact]public void NpcCanInitiateAFundedSmallJobFromKnownLocalDemand(){var setup=NewGameWorldTests.Setup([NewGameWorldTests.Officer("created:idle-a",StartTemplate.Retainer,lord:"person:nobunaga"),NewGameWorldTests.Officer("created:idle-b",StartTemplate.Retainer,lord:"person:nobunaga")]);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,"created:idle-b",42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy));Good(s.ManageBroker(new(Job,BrokerAction.Accept,Issuer:Issuer,Kind:BrokerKind.Purchase),s.Revision));Good(s.ManageBroker(Input(s,BrokerAction.Return),s.Revision));NewGameWorldTests.At(s,86401);Assert.Contains(s.DiagnosticSnapshot().BrokerWork!.Entries,e=>e.Input.Action==BrokerAction.Accept&&e.Actor!=s.PlayerControl);}
}
